{
  "findings": [
    {
      "check_id": "CKV_AWS_69",
      "title": "S3 Bucket Policy is missing comma between elements",
      "resource": "aws_s3_bucket_policy.pass3",
      "severity": "CRITICAL",
      "explanation": "The S3 bucket policy is malformed due to a missing comma between the 'Principal' and 'Effect' elements, which can cause the policy to be ineffective or lead to unintended access."
    }
  ],
  "patched_code": "resource "aws_s3_bucket_policy" "pass3" {
  bucket = "bucket"

  policy = <<POLICY
        {
            "Id": "Policy1597273448050",
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "Stmt1597273446725",
                    "Action": [
                        "s3:GetObject"
                    ],
                    "Resource": "arn:aws:s3:::bucket/*",
                    "Principal": {
                        "AWS": "some_arn"
                    },
                    "Effect": "Deny"
                }
            ]
        }
        POLICY
}
",
  "fix_summary": "Added a missing comma between 'Principal' and 'Effect' elements in the S3 bucket policy to ensure it is properly formatted and effective."
}
